"use client";

import React, { useState, useEffect } from "react";
import QRCode from "react-qr-code"; // Gamit ang library mo

export default function MyQrPage() {
  // Hardcoded muna for testing. Sa totoong system, kukunin ito sa naka-login na user.
  const studentIdNumber = "2024-00123";
  const studentName = "Bryan Lumangaya";
  const program = "Bachelor of Science in Computer Science";

  return (
    <div style={{ padding: "40px 20px", minHeight: "80vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", fontFamily: "'DM Sans', sans-serif" }}>
      
      <div style={{ textAlign: "center", marginBottom: 32, animation: "fadeUp .3s ease" }}>
        <h1 style={{ fontFamily: "'DM Serif Display', serif", fontSize: 32, color: "#1a2744", marginBottom: 8 }}>My Digital Pass</h1>
        <p style={{ color: "#8a8ea8", fontSize: 15 }}>Present this ID to the librarian to process your transactions.</p>
      </div>

      <style>{`
        @keyframes fadeUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
        
        .id-card { 
          background: linear-gradient(145deg, #1a2744 0%, #2a3d6e 100%); 
          width: 100%; 
          max-width: 380px; 
          border-radius: 24px; 
          padding: 40px 24px 0; 
          color: #fff; 
          position: relative; 
          box-shadow: 0 24px 64px rgba(26,39,68,.2); 
          text-align: center; 
          border: 1px solid rgba(255,255,255,.1); 
          animation: fadeUp .4s cubic-bezier(0.16, 1, 0.3, 1); 
          overflow: hidden; 
        }
        
        .id-card::before { 
          content: ''; 
          position: absolute; 
          top: -50px; 
          right: -50px; 
          width: 150px; 
          height: 150px; 
          background: radial-gradient(circle, rgba(61,139,239,.4) 0%, transparent 70%); 
          border-radius: 50%; 
        }
        
        .id-logo { font-family: 'DM Serif Display', serif; font-size: 24px; margin-bottom: 28px; display: flex; align-items: center; justify-content: center; gap: 8px; position: relative; z-index: 2; }
        
        .qr-container { 
          background: #fff; 
          padding: 20px; 
          border-radius: 20px; 
          display: inline-flex; 
          align-items: center; 
          justify-content: center; 
          margin-bottom: 28px; 
          box-shadow: 0 12px 32px rgba(0,0,0,.3); 
          position: relative; 
          z-index: 2;
        }

        .id-name { font-size: 24px; font-weight: 700; margin-bottom: 6px; letter-spacing: 0.5px; position: relative; z-index: 2; }
        .id-program { font-size: 13px; color: rgba(255,255,255,.7); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 28px; position: relative; z-index: 2; }
        
        .id-footer { 
          background: rgba(0,0,0,.2); 
          margin: 0 -24px; 
          padding: 20px 24px; 
          display: flex; 
          justify-content: space-between;
          align-items: center;
          font-size: 13px; 
          color: rgba(255,255,255,.9); 
          border-top: 1px solid rgba(255,255,255,.05); 
          position: relative; 
          z-index: 2;
        }
      `}</style>

      {/* ── DIGITAL ID CARD ── */}
      <div className="id-card">
        <div className="id-logo">
          📚 SmartLib
        </div>

        <div className="qr-container">
          {/* 🚨 PINALAKI ANG SIZE AT GINAWANG 'H' ANG LEVEL PARA SA SCANNER 🚨 */}
          <QRCode 
            value={studentIdNumber} 
            size={220} 
            bgColor="#ffffff" 
            fgColor="#1a2744" 
            level="H" 
          />
        </div>

        <div className="id-name">{studentName}</div>
        <div className="id-program">{program}</div>
        
        <div className="id-footer">
          <span style={{ fontWeight: 600, letterSpacing: "1px" }}>ID: {studentIdNumber}</span>
          <span style={{ color: "#4caf50", fontWeight: "bold", display: "flex", alignItems: "center", gap: "6px" }}>
            <span style={{ width: 8, height: 8, background: "#4caf50", borderRadius: "50%", display: "inline-block", boxShadow: "0 0 8px #4caf50" }}></span>
            Valid
          </span>
        </div>
      </div>
      
      <div style={{ textAlign: "center", marginTop: 32, fontSize: 13, color: "#8a8ea8" }}>
        💡 Tip: Turn your screen brightness up for faster scanning.
      </div>

    </div>
  );
}